def write_json(path, content):
    path.write_text(json.dumps(content, ensure_ascii=False, indent=2), encoding='utf-8')


def main():
    data = ROOT/'dados'
    if (data/'freeze.json').exists():
        raise FileExistsError('Base congelada; criar nova versao para alterar')
    source_path = pathlib.Path('/mnt/c/tcc-lab/Pilot/anime-offline-database-2026-27.json')
    source = json.loads(source_path.read_text(encoding='utf-8'))
    index = {}
    for item in source['data']:
        for url in item['sources']:
            if 'myanimelist.net/anime/' in url:
                index[int(url.rstrip('/').split('/')[-1])] = item
    catalog, raw_subset = [], []
    for mal_id, display, english, portuguese in CATALOG:
        item = index[mal_id]
        raw_subset.append(item)
        catalog.append({'id': str(mal_id), 'title': display, 'source_title': item['title'],
                        'description_en': english, 'description_pt': portuguese,
                        'source_url': f'https://myanimelist.net/anime/{mal_id}',
                        'description_origin': 'Texto curto original preparado com IA para piloto; nao sinopse oficial'})
    ids = {row['id'] for row in catalog}
    assert len(ids) == len(catalog) == 39
    queries, qrels = [], []
    for family, theme, strong, partial, literal_en, para_en, literal_pt, para_pt in INTENTS:
        assert set(str(x) for x in strong+partial) <= ids and not set(strong) & set(partial)
        for style, text_en, text_pt in [('literal', literal_en, literal_pt), ('paraphrase', para_en, para_pt)]:
            query_id = family+'-'+style
            queries.append({'id': query_id, 'family': family, 'theme': theme, 'style': style,
                            'text_en': text_en, 'text_pt': text_pt})
            for row in catalog:
                grade = 2 if int(row['id']) in strong else 1 if int(row['id']) in partial else 0
                qrels.append({'query_id': query_id, 'anime_id': row['id'], 'grade': grade})
    assert len(queries) == 58 and len(qrels) == 58*39
    write_json(data/'catalogo.json', catalog)
    write_json(data/'consultas.json', queries)
    with (data/'relevancia.csv').open('w', newline='', encoding='utf-8') as target:
        writer = csv.DictWriter(target, fieldnames=['query_id','anime_id','grade'])
        writer.writeheader(); writer.writerows(qrels)
    write_json(data/'brutos'/'aod-subconjunto.json', raw_subset)
    with source_path.open('rb') as stream:
        source_sha = hashlib.file_digest(stream, 'sha256').hexdigest()
    files = {path.name: hashlib.sha256(path.read_bytes()).hexdigest()
             for path in [data/'catalogo.json', data/'consultas.json', data/'relevancia.csv']}
    write_json(data/'freeze.json', {
        'frozen_at_utc': datetime.datetime.now(datetime.timezone.utc).isoformat(), 'files_sha256': files,
        'source_release': '2026-27', 'source_last_update': source['lastUpdate'],
        'source_license': source['license'], 'source_sha256': source_sha,
        'items': len(catalog), 'queries': len(queries), 'families': len(INTENTS),
        'qrels': len(qrels), 'all_pairs_judged': True,
        'annotation': 'Descricoes, consultas e julgamentos produzidos com IA; sem validacao humana; piloto curado e nao amostra aleatoria.',
        'primary_scenario_provisional': 'PT_EN',
    })
    print(json.dumps({'items': len(catalog), 'queries': len(queries), 'qrels': len(qrels), 'freeze': files}, indent=2))


if __name__ == '__main__':
    main()
